Initialize using an array of direction types.  Types range from TYPE_MIN to TYPE_MAX inclusive
and represent the direction codes of the characters in the text.

@param types the types array

Initialize using an array of direction types and an externally supplied paragraph embedding level.
The embedding level may be -1, 0, or 1.  -1 means to apply the default algorithm (rules P2 and P3),
0 is for LTR paragraphs, and 1 is for RTL paragraphs.

@param types the types array
@param paragraphEmbeddingLevel the externally supplied paragraph embedding level.

Creates a new TrueType font.
@param ttFile the location of the font on file. The file must end in '.ttf' or
'.ttc' but can have modifiers after the name
@param enc the encoding to be applied to this font
@param emb true if the font is to be embedded in the PDF
@param ttfAfm the font as a byte array
@throws ApplicationException the font is invalid
@throws IOException the font file could not be read

[C#]
private void OnFlush(byte[] data)
{
    // your code
}

public Pdf CreatePdf()
{
    Pdf pdf1 = new Pdf(new MemoryStream());
    pdf1.DirectModeItemsCount = 100000;
    pdf1.DirectModeIte mType = DirectModeItemType.Byte;
    pdf1.DirectModeFlush += OnFlush;
    for (int DocumentCount = 0; DocumentCount <= 1; DocumentCount++)
    {
        //Create a section in the Pdf object 
        Aspose.Pdf.Generator.Section sec1 = pdf1.Sections.Add();
        for (int WordCounter = 0; WordCounter <= 50000; WordCounter++)
        {
            //Create a new text paragraph with an initial text segment "Aspose" 
            Text text1 = new Text();
            Segment textsegment = new Segment("Word # " + WordCounter.ToString());
            text1.Segments.Add(textsegment);
            //Add the text paragraph to the section 
            sec1.AddParagraph(text1);
        }
    }
    //Save the pdf
    pdf1.Close();
}

[VisualBasic]
Private Sub OnFlush(ByVal abArray() As Byte)
    ' your code
End Sub

Private Sub CreatePdf()
   Dim pdf1 As Pdf = New Pdf(New MemoryStream())
   pdf1.DirectModeItemsCount = 100000
   pdf1.DirectModeItemType = DirectModeItemType.Byte
   AddHandler pdf1.DirectModeFlush, AddressOf OnFlush
   For DocumentCount = 0 To 1
       'Create a section in the Pdf object 
       Dim sec1 As Aspose.Pdf.Generator.Section = pdf1.Sections.Add()
       For WordCounter = 0 To 50000
           'Create a new text paragraph with an initial text segment "Aspose" 
           Dim text1 As Text = New Text()
           Dim textsegment As Segment = New Segment("Word # " + WordCounter.ToString())
           text1.Segments.Add(textsegment)
           'Add the text paragraph to the section 
           sec1.AddParagraph(text1)
       Next
   Next
   'Save the pdf

   pdf1.Close()
End Sub

When bytes or pages count in stream exceed DirectModeItemsCount OnFlush event raise

