member.summary:
RevocationInfoArchival ::= SEQUENCE {
    crl [0] EXPLICIT SEQUENCE of CRLs, OPTIONAL
    ocsp [1] EXPLICIT SEQUENCE of OCSP Responses, OPTIONAL
    otherRevInfo [2] EXPLICIT SEQUENCE of OtherRevInfo, OPTIONAL
}
OtherRevInfo ::= SEQUENCE {
                            Type OBJECT IDENTIFIER
                            Value OCTET STRING
}

CertID          ::=     Sequence {
    hashAlgorithm       AlgorithmIdentifier,
    issuerNameHash      OCTET STRING, -- Hash of Issuer's DN
    issuerKeyHash       OCTET STRING, -- Hash of Issuers public key
    serialNumber        CertificateSerialNumber }

CertStatus ::= CHOICE {
                 good        [0]     IMPLICIT Null,
                 revoked     [1]     IMPLICIT RevokedInfo,
                 unknown     [2]     IMPLICIT UnknownInfo }

GeneralName ::= CHOICE {
     otherName                       [0]     OtherName,
     rfc822Name                      [1]     IA5String,
     dNSName                         [2]     IA5String,
     x400Address                     [3]     ORAddress,
     directoryName                   [4]     Name,
     ediPartyName                    [5]     EDIPartyName,
     uniformResourceIdentifier       [6]     IA5String,
     iPAddress                       [7]     OCTET STRING,
     registeredID                    [8]     OBJECT IDENTIFIER}

OtherName ::= Sequence {
     type-id    OBJECT IDENTIFIER,
     value      [0] EXPLICIT ANY DEFINED BY type-id }

EDIPartyName ::= Sequence {
     nameAssigner            [0]     DirectoryString OPTIONAL,
     partyName               [1]     DirectoryString }

RDNSequence ::= SEQUENCE OF RelativeDistinguishedName
   RelativeDistinguishedName ::= SET SIZE (1..MAX) OF AttributeTypeAndValue    
   AttributeTypeAndValue ::= SEQUENCE {
                                  type  OBJECT IDENTIFIER,
                                  value ANY }

OcspRequest     ::=     SEQUENCE {
      tbsRequest                  TBSRequest,
      optionalSignature   [0]     EXPLICIT Signature OPTIONAL }

  TBSRequest      ::=     SEQUENCE {
      version             [0]     EXPLICIT Version DEFAULT v1,
      requestorName       [1]     EXPLICIT GeneralName OPTIONAL,
      requestList                 SEQUENCE OF Request,
      requestExtensions   [2]     EXPLICIT Extensions OPTIONAL }

  Signature       ::=     SEQUENCE {
      signatureAlgorithm      AlgorithmIdentifier,
      signature               BIT STRING,
      certs               [0] EXPLICIT SEQUENCE OF Certificate OPTIONAL}

  Version         ::=    INTEGER  {  v1(0) }

  Request         ::=     SEQUENCE {
     reqCert                     CertID,
     singleRequestExtensions     [0] EXPLICIT Extensions OPTIONAL }

  CertID          ::=     SEQUENCE {
     hashAlgorithm       AlgorithmIdentifier,
     issuerNameHash      OCTET STRING, -- Hash of Issuer's DN
      issuerKeyHash      OCTET STRING, -- Hash of Issuers public key
      serialNumber       CertificateSerialNumber }

Creates a Asn1 sequence.
OcspRequest     ::=     Sequence {
    tbsRequest                 TBSRequest,
   optionalSignature   [0]     EXPLICIT Signature OPTIONAL }

BasicOcspResponse       ::= Sequence {
     tbsResponseData      ResponseData,
     signatureAlgorithm   AlgorithmIdentifier,
    signature            BIT STRING,
    certs                [0] EXPLICIT Sequence OF Certificate OPTIONAL }

OcspResponse ::= Sequence {
    responseStatus         OcspResponseStatus,
    responseBytes          [0] EXPLICIT ResponseBytes OPTIONAL }

ResponderID ::= CHOICE {
     byName          [1] Name,
     byKey           [2] KeyHash }

ResponseBytes ::=       Sequence 
{
    responseType   OBJECT IDENTIFIER,
    response       OCTET STRING 
}

ResponseData ::= Sequence {
    version              [0] EXPLICIT Version DEFAULT v1,
    responderID              ResponderID,
    producedAt               GeneralizedTime,
    responses                Sequence OF SingleResponse,
    responseExtensions   [1] EXPLICIT Extensions OPTIONAL }

Signature       ::=     Sequence {
    signatureAlgorithm      AlgorithmIdentifier,
    signature               BIT STRING,
    certs               [0] EXPLICIT Sequence OF Certificate OPTIONAL}

SingleResponse ::= Sequence {
       certID                       CertID,
       certStatus                   CertStatus,
       thisUpdate                   GeneralizedTime,
       nextUpdate         [0]       EXPLICIT GeneralizedTime OPTIONAL,
       singleExtensions   [1]       EXPLICIT Extensions OPTIONAL }

RevokedInfo ::= Sequence {
     revocationTime              GeneralizedTime,
     revocationReason    [0]     EXPLICIT CRLReason OPTIONAL }

The object that contains the public key stored in a certficate.
SubjectPublicKeyInfo ::= Sequence {
                         algorithm AlgorithmIdentifier,
                         publicKey BIT STRING }

PkiStatusInfo ::= SEQUENCE { status PKIStatus, (INTEGER) statusString PkiFreeText OPTIONAL, failInfo PkiFailureInfo OPTIONAL (BIT STRING) }
PKIStatus: granted (0), -- you got exactly what you asked for grantedWithMods (1), -- you got something like what you asked for rejection (2), -- you don't get it, more information elsewhere in the message waiting (3), -- the request body part has not yet been processed, expect to hear more later revocationWarning (4), -- this message contains a warning that a revocation is imminent revocationNotification (5), -- notification that a revocation has occurred keyUpdateWarning (6) -- update already done for the oldCertId specified in CertReqMsg
PkiFailureInfo: badAlg (0), -- unrecognized or unsupported Algorithm Identifier badMessageCheck (1), -- integrity check failed (e.g., signature did not verify) badRequest (2), -- transaction not permitted or supported badTime (3), -- messageTime was not sufficiently close to the system time, as defined by local policy badCertId (4), -- no certificate could be found matching the provided criteria badDataFormat (5), -- the data submitted has the wrong format wrongAuthority (6), -- the authority indicated in the request is different from the one creating the response token incorrectData (7), -- the requester's data is incorrect (for notary services) missingTimeStamp (8), -- when the timestamp is missing but should be there (by policy) badPOP (9) -- the proof-of-possession failed

PolicyInformation ::= Sequence {
     policyIdentifier   CertPolicyId,
     policyQualifiers   Sequence SIZE (1..MAX) OF
             PolicyQualifierInfo OPTIONAL }

Accuracy ::= SEQUENCE {
            seconds        INTEGER              OPTIONAL,
            millis     [0] INTEGER  (1..999)    OPTIONAL,
            micros     [1] INTEGER  (1..999)    OPTIONAL
            }

MessageImprint ::= SEQUENCE  {
      hashAlgorithm                AlgorithmIdentifier,
      hashedMessage                OCTET STRING  }

EssCertID ::= SEQUENCE {
    certHash Hash,
    issuerSerial IssuerSerial OPTIONAL
}

EssCertIDv2 ::=  SEQUENCE {
    hashAlgorithm     AlgorithmIdentifier
             DEFAULT {algorithm id-sha256},
    certHash          Hash,
    issuerSerial      IssuerSerial OPTIONAL
}

Hash ::= OCTET STRING

IssuerSerial ::= SEQUENCE {
    issuer         GeneralNames,
    serialNumber   CertificateSerialNumber
}

TimeStampResp ::= SEQUENCE  {
 status                  PkiStatusInfo,
 timeStampToken          TimeStampToken     OPTIONAL  }

SigningCertificate ::=  SEQUENCE {
     certs        SEQUENCE OF EssCertID,
     policies     SEQUENCE OF PolicyInformation OPTIONAL
}
id-aa-signingCertificate OBJECT IDENTIFIER ::= { iso(1)
 member-body(2) us(840) rsadsi(113549) pkcs(1) pkcs9(9)
 smime(16) id-aa(2) 12 }

SigningCertificateV2 ::=  SEQUENCE {
     certs        SEQUENCE OF EssCertIDv2,
     policies     SEQUENCE OF PolicyInformation OPTIONAL
}
id-aa-signingCertificateV2 OBJECT IDENTIFIER ::= { iso(1)
   member-body(2) us(840) rsadsi(113549) pkcs(1) pkcs9(9)
   smime(16) id-aa(2) 47 }

member.example:
The example demonstrates how to find text on the first PDF document page and replace the text and it's font.

// Open document
Document doc = new Document(@"D:\Tests\input.pdf");

// Find font that will be used to change document text font
Aspose.Pdf.Txt.Font font = FontRepository.FindFont("Arial");

// Create TextFragmentAbsorber object to find all "hello world" text occurrences
TextFragmentAbsorber absorber = new TextFragmentAbsorber("hello world");

// Accept the absorber for first page
doc.Pages[1].Accept(absorber);

// Change text and font of the first text occurrence
absorber.TextFragments[1].Text = "hi world";
absorber.TextFragments[1].TextState.Font = font;

// Save document
doc.Save(@"D:\Tests\output.pdf");

The example demonstrates how to search a text and replace first occurrence represented with  object .

// Open document
Document doc = new Document(@"D:\Tests\input.pdf");

// Create TextFragmentAbsorber object to find all "hello world" text occurrences
TextFragmentAbsorber absorber = new TextFragmentAbsorber("hello world");

// Accept the absorber for first page
doc.Pages[1].Accept(absorber);

// Change font of the first text occurrence
absorber.TextFragments[1].Text = "hi world";

// Save document
doc.Save(@"D:\Tests\output.pdf");

The example demonstrates how to change text color and font size of the text with  object.

// Open document
Document doc = new Document(@"D:\Tests\input.pdf");

// Create TextFragmentAbsorber object to find all "hello world" text occurrences
TextFragmentAbsorber absorber = new TextFragmentAbsorber("hello world");

// Accept the absorber for first page
doc.Pages[1].Accept(absorber);

// Change foreground color of the first text occurrence
absorber.TextFragments[1].TextState.ForegroundColor = Color.FromRgb(System.Drawing.Color.Red);

// Change font size of the first text occurrence
absorber.TextFragments[1].TextState.FontSize = 15;

// Save document
doc.Save(@"D:\Tests\output.pdf");

The example demonstrates how to navigate all  objects inside .

// Open document
Document doc = new Document(@"D:\Tests\input.pdf");

// Create TextFragmentAbsorber object to find all "hello world" text occurrences
TextFragmentAbsorber absorber = new TextFragmentAbsorber("hello world");

// Accept the absorber for first page
doc.Pages[1].Accept(absorber);

// Navigate all text segments and out their text and placement info
foreach (TextSegment segment in absorber.TextFragments[1].Segments)
{
    Console.Out.WriteLine(string.Format("segment text: {0}", segment.Text));
    Console.Out.WriteLine(string.Format("segment X indent: {0}", segment.Position.XIndent));
    Console.Out.WriteLine(string.Format("segment Y indent: {0}", segment.Position.YIndent));
}

The example demonstrates how to view placement of a text, represented by  object.

 // Open document
 Document doc = new Document(@"D:\Tests\input.pdf");

 // Create TextFragmentAbsorber object to find all "hello world" text occurrences
 TextFragmentAbsorber absorber = new TextFragmentAbsorber("hello world");

 // Accept the absorber for first page
 doc.Pages[1].Accept(absorber);

 // View text and placement info of first text occurrence
 TextFragment firstOccurrence = absorber.TextFragments[1];

 Console.Out.WriteLine(string.Format("fragment text: {0}", firstOccurrence.Text));
 Console.Out.WriteLine(string.Format("fragment X indent: {0}", firstOccurrence.Position.XIndent));
 Console.Out.WriteLine(string.Format("fragment Y indent: {0}", firstOccurrence.Position.YIndent));

